import json, os
S=os.getcwd(); css=open("base.css").read(); word=open("word.html").read()
W1=S+"/../w1"; W2=S+"/../w2"
BG="background:radial-gradient(120% 70% at 85% 0%,#163a2a 0%,#0b1626 55%,#07101c 100%)"
def page(w,h,body): return f"<!doctype html><html><head><meta charset=utf-8><style>{css}</style></head><body><div class='c' style='width:{w}px;height:{h}px'>{body}</div></body></html>"
def img(p,style=""): return f'<img src="file://{p}" style="{style}">'
WIN="display:block;width:100%;border-radius:22px;box-shadow:0 40px 80px -30px #000"
jobs=[]
def add(out,w,h,body,tr=False): jobs.append(dict(w=w,h=h,out=out,transparent=tr,html=page(w,h,body)))
def head(n,tot): return f'<div style="position:absolute;inset:0;{BG}"></div><div style="position:absolute;left:84px;top:84px;transform:scale(.8);transform-origin:left top">{word}</div><p class="mono" style="position:absolute;right:84px;top:92px;font-size:22px;color:#93a6bc">{n} / {tot}</p>'
# ---- A. reel 7 Dec frames (1080x1920) ----
def frame(name,inner,cap):
    add(f"ov/r07-{name}.png",1080,1920,f'<div style="position:absolute;inset:0;{BG}"></div><p style="position:absolute;left:80px;right:80px;top:240px;text-align:center;font:600 76px/1.08 F">{cap}</p><div style="position:absolute;left:70px;right:70px;top:520px;display:flex;justify-content:center">{inner}</div>')
frame("1",img(W1+"/dl/logbook.png","display:none")+img(S+"/../w1/ov/r23-phone.png","width:940px;margin-top:-330px;clip-path:inset(380px 0 160px 0)"),"Your logbook, always up to date")
frame("2",img(W2+"/fm-dark-portrait.png","width:860px;border-radius:24px"),"Your career on one map")
frame("3",img(W2+"/win-ftl.png",WIN),"Your flight time limitations")
frame("4",img(S+"/win-signature-7.5.png",WIN),"Your flights, signed")
add("ov/r07-a.png",1080,1920,'<div style="position:absolute;inset:0;background:#07101cd0"></div><p style="position:absolute;left:80px;right:80px;top:700px;text-align:center;font:600 100px/1.06 F">You don\'t have to wait for the 15th.</p>',True)
add("ov/r07-end.png",1080,1920,f'<div style="position:absolute;inset:0;{BG}"></div><div style="position:absolute;left:0;right:0;top:520px;display:flex;justify-content:center;transform:scale(1.5)">{word}</div><p style="position:absolute;left:80px;right:80px;top:700px;text-align:center;font:600 76px/1.1 F">The web version is open.</p><p class="mono green" style="position:absolute;left:0;right:0;top:900px;text-align:center;font-size:64px;font-weight:700">30 days free · no card</p><p style="position:absolute;left:0;right:0;top:1040px;text-align:center;font-size:40px;color:#c9d4e2">iPhone app on 15.12 · link in bio</p>')
# ---- B. LI 8 Dec pricing ----
plan=lambda n,p,y,items,hi: f'<div style="flex:1;border:2px solid {"#4ade80" if hi else "#ffffff26"};border-radius:26px;padding:34px;background:{"#22c55e14" if hi else "#ffffff08"}"><p style="font:700 34px M">{n}</p><p style="margin-top:14px"><span style="font:800 76px M">{p}</span><span style="font-size:28px;color:#93a6bc"> / month</span></p><p style="font-size:24px;color:#93a6bc;margin-top:6px">{y} / year · 2 months free</p><ul style="margin-top:22px;padding-left:28px;font-size:26px;line-height:1.6;color:#dbe4ee">'+"".join(f"<li>{i}</li>" for i in items)+'</ul></div>'
add("out/li-0812-founder-price.png",1080,1350,f'<div style="position:absolute;inset:0;{BG}"></div><div style="position:absolute;left:84px;top:84px">{word}</div><div style="position:absolute;left:84px;right:84px;top:220px"><p class="mono green" style="font-size:26px;letter-spacing:.16em;font-weight:700">FOUNDER PRICE</p><h1 style="font:600 76px/1.06 F;letter-spacing:-.015em;margin-top:18px">The first 500 subscribers keep their price for as long as they stay.</h1></div><div style="position:absolute;left:84px;right:84px;top:640px;display:flex;gap:24px">'+plan("Basic","€3.99","€39.99",["Unlimited logbook","Exports in EASA, FAA, CASA layouts","Licences & medical","Statistics, web & mobile"],False)+plan("Max","€8.99","€89.99",["Everything in Basic","Rosters & FTL","Layovers, radar, tracks","Audit, CV & job matching"],True)+'</div><p style="position:absolute;left:84px;right:84px;bottom:70px;font-size:30px;color:#c9d4e2">Start with 30 days free, no card · <span class="mono green">geardown.app</span></p>')
# ---- C. IG carousel 9 Dec signatures (5) ----
add("out/ig-0912-signatures-1.png",1080,1350,f'<div style="position:absolute;inset:0;{BG}"></div><div style="position:absolute;left:84px;top:84px">{word}</div><div style="position:absolute;left:84px;right:84px;top:250px"><p class="mono green" style="font-size:26px;letter-spacing:.16em;font-weight:700">SIGNATURES</p><h1 style="font:600 104px/1.0 F;letter-spacing:-.02em;margin-top:20px">Sign your flights with your finger.</h1></div><div style="position:absolute;left:84px;right:84px;top:640px">{img(S+"/win-signature-2.2.png",WIN)}</div><p style="position:absolute;right:84px;bottom:50px;font:700 30px M;color:#4ade80">Swipe →</p>')
def sl(n,title,text,visual):
    add(f"out/ig-0912-signatures-{n}.png",1080,1350,head(n,5)+f'<div style="position:absolute;left:84px;right:84px;top:220px"><h2 style="font:600 72px/1.06 F">{title}</h2><p style="font-size:36px;line-height:1.4;color:#c9d4e2;margin-top:22px">{text}</p><div style="margin-top:56px">{visual}</div></div>')
sl(2,"Saved once, used everywhere","Draw your signature once. Sign one flight, a selection or the whole logbook in a tap.",img(S+"/win-signature-7.5.png",WIN))
req='<div style="border:2px solid #ffffff22;border-radius:22px;padding:26px;font-size:30px">'+"".join(f'<div style="display:flex;justify-content:space-between;align-items:center;padding:16px 0;{"border-top:1px solid #ffffff14" if i else ""}"><span class="mono" style="font-weight:700">{r}</span><span style="font-size:24px;border-radius:999px;padding:6px 16px;background:{bg};color:{c}">{s}</span></div>' for i,(r,s,bg,c) in enumerate([("LSGG → LEMD · 21/11","Signed ✓","#22c55e22","#4ade80"),("EGLL → LSGG · 21/11","Waiting for the captain","#fbbf2422","#fcd34d"),("LSGG → EGLL · 20/11","Waiting for the captain","#fbbf2422","#fcd34d")]))+'</div>'
sl(3,"Ask a captain or instructor","They receive the request and sign from their own phone. You see the signature appear on the flight.",req)
inv='<div style="border:2px solid #f8717155;border-radius:22px;padding:26px;font-size:30px;display:flex;gap:20px;align-items:center"><span style="font:800 44px M;color:#f87171">!</span><span>Flight changed after signing:<br><b style="color:#fca5a5">signature no longer valid</b></span></div>'
sl(4,"A changed flight shows it","If a signed flight is edited later, its signature is marked as no longer valid, so the record stays honest.",inv)
pdf='<div style="background:#f7f5ef;color:#1b2533;border-radius:14px;padding:30px;font:500 22px M;box-shadow:0 30px 60px -20px #000"><p style="font:700 24px J;letter-spacing:.12em">SIGNATURES OF ENTRIES</p>'+"".join(f'<div style="display:grid;grid-template-columns:150px 1fr 220px;gap:16px;align-items:center;padding:12px 0;border-top:1px solid #d9d3c4;margin-top:{10 if i==0 else 0}px"><span class="mono">{d}</span><span class="mono">{r}</span><svg viewBox="0 0 200 40" width="200" height="40"><path d="M6 30 C26 6 40 38 58 18 S92 8 106 28 S140 34 158 14 L194 12" stroke="#1d3d8f" stroke-width="3" fill="none"/></svg></div>' for i,(d,r) in enumerate([("21/11/2026","LSGG → LEMD"),("21/11/2026","EGLL → LSGG"),("20/11/2026","LSGG → EGLL")]))+'</div>'
sl(5,"In your exported logbook","Signatures appear in the PDF export, in an annex next to each entry.",pdf+'<p style="font:700 32px M;margin-top:44px">Save for later 📌 · <span class="mono green">15.12</span></p>')
# ---- D. LI 10 Dec ownership ----
chips=lambda xs,c: "".join(f'<span style="border:2px solid {c};border-radius:999px;padding:14px 28px;font:700 34px J">{x}</span>' for x in xs)
add("out/li-1012-your-logbook.png",1080,1350,f'<div style="position:absolute;inset:0;{BG}"></div><div style="position:absolute;left:84px;top:84px">{word}</div><div style="position:absolute;left:84px;right:84px;top:230px"><p class="mono green" style="font-size:26px;letter-spacing:.16em;font-weight:700">YOUR LOGBOOK BELONGS TO YOU</p><h1 style="font:600 84px/1.04 F;letter-spacing:-.015em;margin-top:20px">Export everything, any time. Even if you stop subscribing.</h1></div><div style="position:absolute;left:84px;right:84px;top:720px"><p style="font-size:28px;color:#93a6bc;letter-spacing:.1em" class="mono">LAYOUTS</p><div style="display:flex;gap:16px;margin-top:16px;flex-wrap:wrap">{chips(["EASA","FAA","CASA"],"#4ade80")}</div><p style="font-size:28px;color:#93a6bc;letter-spacing:.1em;margin-top:44px" class="mono">FILES</p><div style="display:flex;gap:16px;margin-top:16px;flex-wrap:wrap">{chips(["PDF","CSV","Excel"],"#ffffff40")}</div></div><p style="position:absolute;left:84px;right:84px;bottom:70px;font-size:30px;color:#c9d4e2">Opening 15 December · <span class="mono green">geardown.app</span></p>')
# ---- E. reel 11 Dec overlays ----
add("ov/r11-a.png",1080,1920,'<p style="position:absolute;left:80px;right:80px;top:250px;text-align:center;font:600 80px/1.08 F">Medical, licence, type rating, recency.</p>',True)
add("ov/r11-toast.png",1080,300,'<div style="position:absolute;left:60px;right:60px;top:40px;border-radius:34px;background:#1c2b44f0;border:1px solid #ffffff22;padding:26px 30px;display:flex;gap:22px;align-items:center;box-shadow:0 30px 60px -20px #000"><div style="width:76px;height:76px;border-radius:18px;background:#0b1a2e;display:grid;place-items:center;flex-shrink:0"><svg viewBox="0 0 40 40" width="56" height="56"><circle cx="20" cy="13.5" r="5" fill="#22C55E"/><circle cx="11.5" cy="26.5" r="5" fill="#22C55E"/><circle cx="28.5" cy="26.5" r="5" fill="#22C55E"/></svg></div><div><p style="font:700 30px M">Geardown</p><p style="font-size:30px;color:#dbe4ee">Your Class 1 medical expires in 25 days.</p></div></div>',True)
add("ov/r11-end.png",1080,1920,f'<div style="position:absolute;inset:0;{BG}"></div><div style="position:absolute;left:0;right:0;top:560px;display:flex;justify-content:center;transform:scale(1.5)">{word}</div><p style="position:absolute;left:80px;right:80px;top:740px;text-align:center;font:600 72px/1.1 F">Never miss an expiry again.</p><p class="mono green" style="position:absolute;left:0;right:0;top:960px;text-align:center;font-size:110px;font-weight:700">4 days</p>')
# ---- F. story 12 Dec ----
add("out/ig-1212-story-3days.png",1080,1920,f'<img src="file://{W1}/dusk.png" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:62% 50%"><div style="position:absolute;inset:0;background:linear-gradient(180deg,#07101cdd 0%,#07101c40 40%,#07101c66 62%,#07101cee 100%)"></div><div style="position:absolute;left:0;right:0;top:250px;display:flex;justify-content:center">{word}</div><p class="mono" style="position:absolute;left:0;right:0;top:420px;text-align:center;font-size:200px;font-weight:700;color:#fff;text-shadow:0 6px 40px #0008">3 days</p><p style="position:absolute;left:0;right:0;bottom:330px;text-align:center;font:600 64px F">Try it now: 30 days free</p><p style="position:absolute;left:0;right:0;bottom:260px;text-align:center;font-size:34px;color:#c9d4e2">Link below ↓</p>')
json.dump(jobs,open("jobs3.json","w")); print(len(jobs))
